WITH inner_cte AS ( SELECT m.MASTER_DEPT_HIER_LEVEL_2_NAME, f.ORGANIZATION_NAME, COUNT(f.FCLT_ORGANIZATION_KEY) AS organization_count, MIN(f.ORGANIZATION_NUMBER) AS min_organization_number FROM MASTER_DEPT_HIERARCHY m JOIN FCLT_ORGANIZATION f ON m.DLC_KEY = f.DLC_KEY WHERE f.ASSIGNABLE = 1 GROUP BY m.MASTER_DEPT_HIER_LEVEL_2_NAME, f.ORGANIZATION_NAME ), org_geom_supervisees AS ( SELECT FCLT_ORGANIZATION.ORGANIZATION_NAME, EXP(AVG(LN(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES))) AS geometric_mean_supervisees FROM FCLT_ORGANIZATION JOIN SPACE_UNIT ON FCLT_ORGANIZATION.DLC_KEY = SPACE_UNIT.DLC_KEY JOIN SPACE_SUPERVISOR_USAGE ON SPACE_UNIT.DLC_KEY = SPACE_SUPERVISOR_USAGE.DEPT_NAMES WHERE SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES > 0 GROUP BY FCLT_ORGANIZATION.ORGANIZATION_NAME ), org_total_research_volume AS ( SELECT FCLT_ORGANIZATION.ORGANIZATION_NAME, SUM(SPACE_SUPERVISOR_USAGE.RESEARCH_VOLUME) AS total_research_volume FROM FCLT_ORGANIZATION JOIN SPACE_UNIT ON FCLT_ORGANIZATION.DLC_KEY = SPACE_UNIT.DLC_KEY JOIN SPACE_SUPERVISOR_USAGE ON SPACE_UNIT.DLC_KEY = SPACE_SUPERVISOR_USAGE.DEPT_NAMES WHERE SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES > 0 GROUP BY FCLT_ORGANIZATION.ORGANIZATION_NAME ) SELECT i.MASTER_DEPT_HIER_LEVEL_2_NAME, i.ORGANIZATION_NAME, i.organization_count, i.min_organization_number, o.geometric_mean_supervisees, r.total_research_volume FROM inner_cte i LEFT JOIN org_geom_supervisees o ON i.ORGANIZATION_NAME = o.ORGANIZATION_NAME LEFT JOIN org_total_research_volume r ON i.ORGANIZATION_NAME = r.ORGANIZATION_NAME ORDER BY i.organization_count DESC, o.geometric_mean_supervisees DESC, r.total_research_volume DESC;